1	/* PhishSense colors: navy + teal, matching the logo */
2	:root {
3	  --navy: #0a1a33;
4	  --navy-2: #123a5c;
5	  --teal: #2de0c4;
6	  --text: #e9f1f7;
7	  --muted: #9fb7c9;
8	  --red: #ff5d6c;
9	  --green: #3ddc84;
10	  /* Difficulty colors: buttons, badge icons, mission title */
11	  --easy: #4ade80;     /* Minnow */
12	  --medium: #facc15;   /* Angler */
13	  --hard: #f87171;     /* Captain */
14	  --easy-tint: rgba(74, 222, 128, 0.14);
15	  --medium-tint: rgba(250, 204, 21, 0.14);
16	  --hard-tint: rgba(248, 113, 113, 0.14);
17	  --fit-h: none; /* set on large screens: the height a screen must fit in */
18	}
19	
20	* { box-sizing: border-box; }
21	
22	/* ---------- Bootstrap overrides ----------
23	   Bootstrap is loaded for its grid only. Its base styles ("reboot") change
24	   fonts, spacing, and headings, so these put our original look back. */
25	:root { scroll-behavior: auto; }   /* the link popup measures right after scrolling */
26	body {
27	  margin: 0;
28	  font-family: "Inter", Arial, sans-serif;
29	  font-size: 1rem;   /* 16px; grows a little on very wide screens (see below) */
30	  line-height: normal;
31	  background: var(--navy);
32	  color: var(--text);
33	}
34	h1, h2, h3 { color: inherit; font-weight: bold; line-height: normal; }
35	h2 { font-size: 1.5em; margin: 0.83em 0; }
36	h3 { font-size: 1.17em; margin: 1em 0; }
37	p { margin: 1em 0; }
38	ul, ol { margin: 1em 0; padding-left: 40px; }
39	small { font-size: smaller; }
40	.container { max-width: 1200px; }   /* one width at every breakpoint, centered */
41	
42	/* ---------- Headers ---------- */
43	/* Big centered header on the home screen */
44	.hero { text-align: center; padding: 32px 16px 8px; }
45	.hero h1 { margin: 0; font-size: 44px; font-weight: 800; }
46	.hero h1 span { color: var(--teal); }
47	.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
48	.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }
49	
50	/* Slim top bar on every other screen */
51	.topbar { display: none; border-bottom: 1px solid rgba(159, 183, 201, 0.15); background: #0c1f3b; }
52	body:not([data-screen="start-screen"]) .hero { display: none; }
53	body:not([data-screen="start-screen"]) .topbar { display: block; }
54	.topbar-inner {
55	  padding-top: 8px; padding-bottom: 8px; min-height: 52px;
56	  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px;
57	}
58	.brand { display: flex; align-items: center; gap: 10px; }
59	.brand-logo { width: 36px; height: 36px; display: block; }
60	.brand-name { font-size: 20px; font-weight: 800; }
61	.brand-name span { color: var(--teal); }
62	
63	/* Run status: shown while playing, and as a final summary on the end screen */
64	.run-status { display: none; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-left: auto; }
65	body[data-screen="play-screen"] .run-status,
66	body[data-screen="end-screen"] .run-status { display: flex; }
67	body[data-screen="end-screen"] .streak,
68	body[data-screen="end-screen"] .contacts-toggle { display: none; }
69	.run-info { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
70	.round-counter { margin: 0; font-size: 14px; color: var(--muted); white-space: nowrap; }
71	
72	/* ---------- Page ---------- */
73	main { padding-top: 16px; padding-bottom: 16px; }
74	body:not([data-screen="start-screen"]) main { padding-top: 32px; }   /* gap under the top bar */
75	.hidden { display: none !important; }
76	
77	/* Home: one centered column */
78	.home-col { max-width: 800px; }
79	
80	/* Mission: two cards side by side on large screens, same height.
81	   Uses the full container width, so its edges line up with the play screen and the logo. */
82	#mission-screen .ps-card { margin: 0; height: 100%; }
83	
84	/* Scroll areas inside cards get a dark scrollbar that matches the theme */
85	.ps-card, .email .body, .sms .bubble { scrollbar-width: thin; scrollbar-color: #3a6185 transparent; }
86	
87	/* Start screen */
88	.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
89	.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
90	.step-label + input { margin-top: 0; }
91	#start-screen .leaderboard { margin-top: 24px; }
92	
93	/* Mission screen */
94	.briefing { margin-top: 0; line-height: 1.6; color: var(--muted); }
95	.briefing p { margin: 0 0 10px; }
96	.briefing p:last-child { margin-bottom: 0; }
97	.briefing b { color: var(--text); }
98	.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
99	.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
100	.mission-mode.tier-easy, .mission-mode.tier-medium, .mission-mode.tier-hard { color: var(--tier); }
101	.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
102	.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
103	button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }
104	
105	input {
106	  display: block; width: 100%; margin: 0; padding: 12px;
107	  border-radius: 10px; border: 1px solid var(--navy-2);
108	  background: var(--navy-2); color: var(--text); font-size: 1rem;
109	}
110	
111	button {
112	  font-family: inherit; font-size: 1rem; font-weight: 600; line-height: normal; cursor: pointer;
113	  border: none; border-radius: 10px; padding: 12px 18px;
114	  background: var(--teal); color: var(--navy);
115	}
116	button:disabled { opacity: 0.5; cursor: default; }
117	
118	.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
119	/* Each difficulty sets --tier; anything tagged with it (icons, the mission title) uses that color */
120	.tier-easy { --tier: var(--easy); --tier-tint: var(--easy-tint); }
121	.tier-medium { --tier: var(--medium); --tier-tint: var(--medium-tint); }
122	.tier-hard { --tier: var(--hard); --tier-tint: var(--hard-tint); }
123	.tier-easy, .tier-medium, .tier-hard { color: var(--tier); }
124	
125	/* Badge icon: sized to the text around it, drawn in currentColor */
126	.badge-icon { display: inline-block; width: 1.15em; height: 1.15em; vertical-align: -0.2em; margin-right: 0.3em; }
127	.badge-label { white-space: nowrap; }
128	
129	/* Difficulty buttons: colored border, light tint on hover, text stays white on the dark card */
130	button.mode {
131	  padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--tier);
132	  transition: background-color 0.15s ease;
133	}
134	button.mode:hover, button.mode:focus-visible {
135	  background: linear-gradient(var(--tier-tint), var(--tier-tint)) var(--navy-2);
136	}
137	button.mode:focus-visible { outline: 2px solid var(--tier); outline-offset: 2px; }
138	.mode .badge-icon { width: 1.3em; height: 1.3em; vertical-align: -0.3em; }
139	.mode small { color: var(--muted); font-weight: 400; }
140	
141	/* Our card style (named ps-card so Bootstrap's .card doesn't restyle it) */
142	.ps-card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
143	.ps-card.good { border-left: 6px solid var(--green); }
144	.ps-card.bad { border-left: 6px solid var(--red); }
145	
146	.loading { color: var(--muted); text-align: center; padding: 24px; }
147	
148	/* ---------- Play layout (Bootstrap grid: col-lg-7 message, col-lg-5 answers) ---------- */
149	#play-screen .ps-card { margin: 0; }
150	.message-wrap { position: relative; }
151	#result h3 { margin-top: 0; }
152	#result p:last-child, #result ul:last-child { margin-bottom: 0; }
153	
154	/* Phones and narrow windows: one column.
155	   The answer column's box is dissolved so its pieces stack under the message
156	   (buttons, reaction, result, Next), and the contacts panel can move to the top. */
157	@media (max-width: 991.98px) {
158	  .play-side { display: contents; }
159	  #play-screen .play-side > * {
160	    flex-shrink: 0;
161	    width: calc(100% - var(--bs-gutter-x));
162	    margin: var(--bs-gutter-y) calc(var(--bs-gutter-x) * 0.5) 0;
163	  }
164	  #play-screen #contacts-panel { order: -1; }   /* opens right under the top bar */
165	}
166	
167	/* Large screens: two columns, sized so a whole round fits without scrolling */
168	@media (min-width: 992px) {
169	  :root { --fit-h: calc(100vh - 104px); }
170	  @supports (height: 100dvh) { :root { --fit-h: calc(100dvh - 104px); } }
171	
172	  .play-side { display: flex; flex-direction: column; gap: 12px; max-height: var(--fit-h); }
173	  .play-side > * { flex: 0 0 auto; }
174	  .contacts-panel .contacts-table th, .contacts-panel .contacts-table td { padding: 6px; }
175	
176	  /* Long explanations scroll inside the card, so Next stays on screen */
177	  #result.ps-card { flex: 0 1 auto; min-height: 0; overflow-y: auto; padding: 14px 16px; font-size: 15px; line-height: 1.45; }
178	  #result ul { padding-left: 20px; margin: 6px 0 10px; }
179	  #result li { margin: 3px 0; }
180	  #result p { margin: 8px 0; }
181	
182	  .answer { padding: 18px; font-size: 18px; }
183	  #btn-next { width: 100%; margin: 0; }
184	
185	  /* Long messages scroll inside the message, never the page */
186	  .email, .sms { display: flex; flex-direction: column; max-height: var(--fit-h); }
187	  .email > *, .sms > * { flex: 0 0 auto; }
188	  .email .body { flex: 0 1 auto; min-height: 60px; overflow-y: auto; }
189	  .sms .bubble { flex: 0 1 auto; min-height: 48px; overflow-y: auto; }
190	
191	  /* End screen: badge on the left, recap + leaderboard on the right */
192	  .end-side { display: flex; flex-direction: column; gap: 16px; max-height: var(--fit-h); }
193	  .end-side > .ps-card { flex: 0 1 auto; min-height: 0; overflow-y: auto; }
194	  .end-side > .leaderboard { flex-shrink: 0; max-height: 45%; }   /* the recap gives up room first */
195	  .end-side > .recap { flex-grow: 1; }   /* fills spare height so both columns end together */
196	  .end-main { display: flex; }   /* the card fills the column, which matches the right column's height */
197	  .end-card { flex: 1 1 auto; }
198	}
199	
200	/* Very wide screens: text grows from 16px (at 1600px) to 18px (at 2000px and up).
201	   Everything sized in rem/em follows; phones and laptops keep 16px. */
202	@media (min-width: 1601px) {
203	  html { font-size: clamp(16px, calc(8px + 0.5vw), 18px); }
204	}
205	
206	/* Shorter laptop screens: a smaller home header so the home screen fits too */
207	@media (min-width: 992px) and (max-height: 800px) {
208	  .hero { padding-top: 18px; }
209	  .logo { width: 90px; margin-bottom: 4px; }
210	}
211	
212	/* ---------- Run status: progress dots + streak ---------- */
213	.dots { display: flex; gap: 8px; }
214	.dot {
215	  width: 14px; height: 14px; border-radius: 50%;
216	  background: transparent; border: 2px solid #2b4a68;
217	  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
218	}
219	.dot.current { border-color: var(--teal); transform: scale(1.2); }
220	.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
221	.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }
222	
223	.streak { margin: 0; font-size: 14px; font-weight: 600; color: var(--teal); white-space: nowrap; }
224	.streak:empty { display: none; }
225	
226	/* ---------- Trusted contacts (briefing card + play panel) ---------- */
227	.contacts-toggle {
228	  font-size: 13px; padding: 6px 12px; border-radius: 999px; white-space: nowrap;
229	  background: transparent; color: var(--text); border: 2px solid var(--navy-2);
230	}
231	.contacts-toggle:hover, .contacts-toggle.open { border-color: var(--teal); }
232	.contacts-toggle.open { background: rgba(45, 224, 196, 0.12); }
233	
234	.contacts-title {
235	  margin: 0 0 10px; font-size: 13px; font-weight: 600;
236	  letter-spacing: 2px; text-transform: uppercase; color: var(--teal);
237	}
238	.contacts-panel { border: 1px solid #2b4a68; }
239	.contacts-table { width: 100%; border-collapse: collapse; font-size: 14px; }
240	.contacts-table th, .contacts-table td {
241	  text-align: left; vertical-align: top; padding: 8px 6px;
242	  border-bottom: 1px solid rgba(159, 183, 201, 0.18);
243	}
244	.contacts-table thead th {
245	  padding-top: 0; font-size: 12px; font-weight: 600; color: var(--muted);
246	}
247	.contacts-table tbody th { font-weight: 600; color: var(--text); }
248	.contacts-table tbody th small { display: block; font-weight: 400; font-size: 12px; color: var(--muted); }
249	.contact-domain, .contact-phone { display: block; font-family: monospace; font-size: 14px; color: var(--teal); overflow-wrap: anywhere; }
250	.contact-phone { color: var(--text); }
251	.contacts-tip { margin: 10px 0 0; font-size: 13px; color: var(--muted); }
252	
253	/* ---------- Message area: glow, shake, floating score ---------- */
254	.message-wrap { position: relative; }
255	.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
256	.pop-score {
257	  position: absolute; left: 50%; top: 24%;
258	  font-size: 40px; font-weight: 800; color: var(--green);
259	  text-shadow: 0 2px 12px rgba(10, 26, 51, 0.8);
260	  animation: float-up 1.3s ease-out forwards;
261	}
262	
263	#message.is-correct .email,
264	#message.is-correct .sms { animation: glow-green 1.1s ease-out; }
265	#message.is-wrong { animation: shake 0.45s ease-in-out; }
266	
267	/* ---------- Answer reactions ---------- */
268	/* Keeps a tilted card from adding a sideways scrollbar while the hook pulls it */
269	body { overflow-x: clip; }
270	
271	#message.hook-anim { position: relative; z-index: 50; animation: none; }
272	#message.is-hooked .email,
273	#message.is-hooked .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
274	#message.is-cautious .email,
275	#message.is-cautious .sms { box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.6), 0 10px 30px rgba(0, 0, 0, 0.35); }
276	
277	.hook-rig {
278	  position: absolute; z-index: 60; width: 0; height: 0;
279	  pointer-events: none; transform-origin: 0 0; will-change: transform;
280	}
281	.hook-line {
282	  position: absolute; left: -1px; top: 0;
283	  width: 2px; height: var(--drop);
284	  background: #dfe7ee; box-shadow: 0 0 0 1px rgba(10, 26, 51, 0.55);
285	}
286	.hook {
287	  position: absolute; left: -20px; top: calc(var(--drop) - 1px);
288	  overflow: visible; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.35));
289	}
290	
291	.reaction {
292	  margin: 0; padding: 12px 16px; border-radius: 12px;
293	  text-align: center; font-size: 20px; font-weight: 800; line-height: 1.3;
294	  animation: reaction-pop 0.35s cubic-bezier(0.2, 0.8, 0.3, 1.25) both;
295	}
296	.reaction.hooked {
297	  color: #ffc2c8; background: rgba(255, 93, 108, 0.14); border: 2px solid var(--red);
298	  animation-delay: 0.45s; /* appears as the hook bites */
299	}
300	.reaction.dodged {
301	  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
302	  animation-delay: 0.35s; /* appears as the card ducks */
303	}
304	.reaction.safe {
305	  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
306	}
307	/* Friendly, not harsh: soft amber, a gentle fade instead of a pop */
308	.reaction.cautious {
309	  color: #ffe3a3; background: rgba(255, 209, 102, 0.1);
310	  border: 2px solid rgba(255, 209, 102, 0.45);
311	  font-weight: 700; animation-name: reaction-soft; animation-duration: 0.4s;
312	}
313	.ps-card.gentle { border-left: 6px solid #ffd166; }
314	.gentle-tip { margin-bottom: 0; color: #ffe3a3; }
315	
316	@keyframes reaction-pop {
317	  0% { opacity: 0; transform: scale(0.85); }
318	  100% { opacity: 1; transform: scale(1); }
319	}
320	@keyframes reaction-soft {
321	  0% { opacity: 0; transform: translateY(6px); }
322	  100% { opacity: 1; transform: translateY(0); }
323	}
324	
325	@keyframes dot-pop {
326	  0% { transform: scale(0.6); }
327	  60% { transform: scale(1.35); }
328	  100% { transform: scale(1); }
329	}
330	@keyframes float-up {
331	  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
332	  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
333	  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
334	}
335	@keyframes glow-green {
336	  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
337	  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
338	  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
339	}
340	@keyframes shake {
341	  10%, 90% { transform: translateX(-3px); }
342	  20%, 80% { transform: translateX(5px); }
343	  30%, 50%, 70% { transform: translateX(-9px); }
344	  40%, 60% { transform: translateX(9px); }
345	}
346	
347	/* ---------- Email: looks like an inbox message ---------- */
348	#message.ps-card { padding: 0; background: none; }
349	.email {
350	  background: #f7f9fb; color: #1b2a3a;
351	  border-radius: 14px; overflow: hidden;
352	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
353	}
354	.email::before {
355	  content: "INBOX";
356	  display: block; padding: 10px 18px;
357	  background: #dfe7ee; color: #45566a;
358	  font-size: 13px; font-weight: 600; letter-spacing: 1px;
359	}
360	.email-head {
361	  display: flex; align-items: flex-start; gap: 12px;
362	  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
363	}
364	.avatar {
365	  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
366	  background: var(--navy-2); color: #fff;
367	  display: flex; align-items: center; justify-content: center;
368	  font-size: 18px; font-weight: 800;
369	}
370	.email-who { flex: 1 1 auto; min-width: 0; }
371	.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
372	.email-who .from b { color: #1b2a3a; }
373	.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
374	.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }
375	
376	.email .body { margin: 0; padding: 18px; line-height: 1.6; }
377	
378	.email-actions {
379	  display: flex; gap: 10px;
380	  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
381	}
382	.email-actions button,
383	.email-actions button:disabled {
384	  font-size: 14px; padding: 8px 16px; border-radius: 8px;
385	  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
386	  opacity: 1; cursor: not-allowed;
387	}
388	
389	/* ---------- Text message: looks like a phone ---------- */
390	.sms {
391	  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
392	  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
393	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
394	}
395	.sms::before {
396	  content: ""; display: block; width: 90px; height: 6px;
397	  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
398	}
399	
400	/* Phone status bar: time, signal bars, battery */
401	.status-bar {
402	  display: flex; align-items: center; justify-content: space-between;
403	  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
404	}
405	.sb-right { display: flex; align-items: center; gap: 7px; }
406	.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
407	.signal i { width: 3px; background: var(--text); border-radius: 1px; }
408	.signal i:nth-child(1) { height: 4px; }
409	.signal i:nth-child(2) { height: 6px; }
410	.signal i:nth-child(3) { height: 9px; }
411	.signal i:nth-child(4) { height: 11px; }
412	.battery {
413	  position: relative; width: 25px; height: 13px;
414	  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
415	}
416	.battery::after {
417	  content: ""; position: absolute; right: -4px; top: 3.5px;
418	  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
419	}
420	.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }
421	
422	.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
423	.sms .label b { display: block; font-size: 16px; color: var(--text); }
424	.bubble {
425	  background: #e9edf2; color: #1b2a3a;
426	  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
427	  line-height: 1.5; margin: 0; max-width: 85%;
428	}
429	
