// Static server for public/ + Chrome DevTools Protocol screenshots of every screen.
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";

const ROOT = process.argv[2];
const OUT = process.argv[3];
const types = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript", ".svg": "image/svg+xml" };
const server = http.createServer((req, res) => {
  const p = path.join(ROOT, decodeURIComponent(req.url.split("?")[0]) === "/" ? "index.html" : req.url.split("?")[0]);
  fs.readFile(p, (err, data) => {
    if (err) { res.writeHead(404); return res.end(); }
    res.writeHead(200, { "Content-Type": types[path.extname(p)] || "application/octet-stream" });
    res.end(data);
  });
}).listen(4173);

const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new", "--remote-debugging-port=9333", "--no-first-run",
  `--user-data-dir=${path.join(OUT, "profile")}`, "about:blank",
]);
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 40 && !target; i++) {
  await wait(250);
  try { target = (await (await fetch("http://127.0.0.1:9333/json")).json()).find((t) => t.type === "page"); } catch {}
}
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const js = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result?.result?.value;
const shot = async (name) => {
  await wait(600);
  const r = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync(path.join(OUT, name + ".png"), Buffer.from(r.result.data, "base64"));
};

const sizes = [[1920, 1080, "1920"], [1366, 768, "1366"], [375, 812, "375"]];
const report = [];
for (const [w, h, tag] of sizes) {
  await send("Emulation.setDeviceMetricsOverride", { width: w, height: h, deviceScaleFactor: 1, mobile: w < 500 });
  await send("Page.navigate", { url: "http://127.0.0.1:4173/" });
  await wait(1500);
  report.push({ tag, bubblesShown: await js(`getComputedStyle(document.querySelector('.bg-bubble')).display`),
    pe: await js(`getComputedStyle(document.querySelector('.ocean-bg')).pointerEvents`),
    hScroll: await js(`document.documentElement.scrollWidth > innerWidth`),
    topAtWave: await js(`document.elementFromPoint(innerWidth/2, innerHeight-20)?.className || document.elementFromPoint(innerWidth/2, innerHeight-20)?.tagName`) });
  await shot(`${tag}-home`);
  await js(`document.getElementById('username').value='Tester'; document.querySelector('[data-mode="medium"]').click()`);
  await shot(`${tag}-mission`);
  await js(`document.getElementById('btn-start').click()`);
  await wait(1200);
  await shot(`${tag}-play`);
  for (let r = 0; r < 5; r++) {
    await js(`document.getElementById('btn-phish').click()`);
    await wait(1800);
    if (r === 0) await shot(`${tag}-play-result`);
    await js(`document.getElementById('btn-next').click()`);
    await wait(1200);
  }
  await wait(1500);
  await shot(`${tag}-end`);
}
// Reduced motion check
await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-reduced-motion", value: "reduce" }] });
await send("Emulation.setDeviceMetricsOverride", { width: 1366, height: 768, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: "http://127.0.0.1:4173/" });
await wait(1200);
report.push({ reduced: await js(`getComputedStyle(document.querySelector('.wave')).animationName + ' / bubbles ' + getComputedStyle(document.querySelector('.bg-bubble')).display + ' / wave visible ' + getComputedStyle(document.querySelector('.wave')).display`) });
console.log(JSON.stringify(report, null, 1));
chrome.kill(); server.close(); process.exit(0);

